  "blake snell": { id: "18356", slug: "blake-snell" },
  "ivan herrera": { id: "20857", slug: "ivan-herrera" },
  "iván herrera": { id: "20857", slug: "ivan-herrera" },
  "jojo romero": { id: "20195", slug: "jojo-romero" },
  "jordan walker": { id: "48376", slug: "jordan-walker" },
